import React, { useState } from 'react';

interface AgentCapsuleProps {
  agentName: string;
  thought: string;
  variant: 'design' | 'code' | 'art' | 'qa';
  isExpandable?: boolean;
}

const variantStyles = {
  design: { bg: 'bg-[#3B82F6]/15', text: 'text-[#3B82F6]', dot: 'bg-[#3B82F6]' },
  code: { bg: 'bg-[#10B981]/15', text: 'text-[#10B981]', dot: 'bg-[#10B981]' },
  art: { bg: 'bg-[#8B5CF6]/15', text: 'text-[#8B5CF6]', dot: 'bg-[#8B5CF6]' },
  qa: { bg: 'bg-[#F59E0B]/15', text: 'text-[#F59E0B]', dot: 'bg-[#F59E0B]' },
};

export function AgentCapsule({ agentName, thought, variant, isExpandable }: AgentCapsuleProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const styles = variantStyles[variant];
  const displayText = thought || `${agentName} is working...`;

  const content = (
    <div className={`
      inline-flex items-center gap-2 px-3 py-1 rounded-full
      ${styles.bg} ${styles.text}
      text-[clamp(12px,3.2vw,14px)]
    `}>
      <span className={`w-2 h-2 rounded-full ${styles.dot}`} />
      <span className={isExpanded ? '' : 'line-clamp-1'}>{displayText}</span>
    </div>
  );

  if (!isExpandable) return content;

  return (
    <button
      onClick={() => setIsExpanded(!isExpanded)}
      aria-expanded={isExpanded}
      className="inline-block text-left"
    >
      {content}
    </button>
  );
}

